def list_suppliers():
    return list(SUPPLIERS.keys())


def list_door_types(supplier):
    return list(SUPPLIERS.get(supplier, {}).get("door_types", {}).keys())


def list_ranges(supplier, door_type):
    dt = SUPPLIERS.get(supplier, {}).get("door_types", {}).get(door_type)
    if not dt:
        return []
    ranges = dt.get("ranges", [])
    return ranges if isinstance(ranges, list) else list(ranges.keys())


def list_colours(supplier, door_type, range_name=None):
    """
    Colours can live at the door_type level (shared across every range —
    true for OS Doors' 5G Vinyl, where the 8 styles are just different
    door faces cut to the same 46 finishes) or per-range (true for
    everything else, where each named range is a genuinely different
    door design with its own colour options).
    """
    dt = SUPPLIERS.get(supplier, {}).get("door_types", {}).get(door_type)
    if not dt:
        return []
    if "colours" in dt:
        return dt["colours"]
    if not isinstance(dt.get("ranges"), dict):
        return []
    r = dt["ranges"].get(range_name)
    return r["colours"] if r else []


def standard_sizes(supplier, door_type, range_name=None):
    """
    (height_mm, width_mm) pairs available as standard stock sizes.
    Checked per-range first (a range can have its own size grid, e.g.
    OS Doors' Fenwick), falling back to a door_type-level grid shared
    across all ranges (e.g. Trade Mouldings' MTM Vinyl — one grid,
    five different-coloured ranges built to it).
    """
    dt = SUPPLIERS.get(supplier, {}).get("door_types", {}).get(door_type)
    if not dt:
        return []
    if isinstance(dt.get("ranges"), dict):
        r = dt["ranges"].get(range_name, {})
        if r.get("standard_sizes_hxw_mm"):
            return [tuple(s) for s in r["standard_sizes_hxw_mm"]]
    return [tuple(s) for s in dt.get("standard_sizes_hxw_mm", [])]


def size_convention(supplier, door_type, range_name=None):
    """
    'cut' (default): the size grid lists actual door-cut sizes, already
    net of the manufacturing reveal — true for OS Doors, and for Trade
    Mouldings' Larissa range specifically (its own price list uses odd,
    reveal-adjusted numbers like 447/497/547mm, not round nominal
    sizes — a genuine per-range difference from the rest of Trade
    Mouldings).
    'nominal': the size grid lists the cabinet OPENING size before the
    reveal is taken off — true for Trade Mouldings' other ranges
    (confirmed with Marcus: same reveal idea as OS Doors, just quoted
    against the opening rather than the finished door). A range can
    override its door_type's default convention this way.
    """
    dt = SUPPLIERS.get(supplier, {}).get("door_types", {}).get(door_type, {})
    if isinstance(dt.get("ranges"), dict) and range_name in dt["ranges"]:
        r = dt["ranges"][range_name]
        if "size_convention" in r:
            return r["size_convention"]
    return dt.get("size_convention", "cut")


def is_standard_size(supplier, door_type, height_mm, width_mm, range_name=None):
    return (height_mm, width_mm) in standard_sizes(supplier, door_type, range_name)


def nearest_standard_size(supplier, door_type, height_mm, width_mm, range_name=None, tolerance_mm=3):
    """
    The real catalogue size closest to a computed (height, width), if
    one exists within tolerance_mm on both axes — used to snap a
    formula-derived size onto the real stocked size, since exact
    reveal conventions vary (confirmed: 4mm is Marcus's rough
    guideline, not a hard rule — always prefer the real number where
    the catalogue has one). Returns None if nothing is close enough,
    meaning it should be quoted as Made to Measure instead.
    """
    best, best_dist = None, None
    for h, w in standard_sizes(supplier, door_type, range_name):
        dh, dw = abs(h - height_mm), abs(w - width_mm)
        if dh <= tolerance_mm and dw <= tolerance_mm:
            dist = dh + dw
            if best_dist is None or dist < best_dist:
                best, best_dist = (h, w), dist
    return best


# Cabinet construction reference — from Trade Mouldings' own cabinet
# range (their Cabinets section, pages 63-70). We don't buy cabinet
# boxes from Trade Mouldings, but these numbers cross-check cleanly
# against the assumptions already built into the quoting engine:
#   - Base unit height 720mm, matches TALL_CABINET_SPLIT_MM in main.py.
#   - Base/tall unit depth 570mm, wall unit depth 330mm.
#   - Plinth/feet height 150mm, matches the Kickboard height band in
#     classify_trim.
# The Larder and Appliance Housing door splits below are the actual
# source for APPLIANCE_HOUSING_SPLITS_MM in main.py (already corrected
# for the bottom/top mislabelling in Trade Mouldings' own PDF text —
# confirmed with Marcus).
# End panel standard sizes (Length x Width, mm, 18mm thick) — from OS
# Doors' own panel accessory pages. Three panel types share broadly
# similar sizes but aren't identical:
PANEL_STANDARD_SIZES = {
    "OS Doors": {
        "Flat Laminated Panel": [(785, 380), (930, 650), (965, 380), (2400, 650), (2620, 650)],
        "Pressed Plain Panel": [(785, 360), (900, 650), (900, 1200), (965, 360), (2400, 360), (2400, 650)],
        "Pressed T&G Panel": [(785, 360), (900, 650), (900, 1200), (965, 360), (2400, 360), (2400, 650)],
    },
}


def panels_priced_as_door(supplier, door_type, range_name):
    """True if this range has no separate panel size list — panels use
    the same size grid as its doors (confirmed: Trade Mouldings'
    Fenton range states this directly, "Panel priced as Door")."""
    dt = SUPPLIERS.get(supplier, {}).get("door_types", {}).get(door_type, {})
    if isinstance(dt.get("ranges"), dict) and range_name in dt["ranges"]:
        return bool(dt["ranges"][range_name].get("panel_priced_as_door"))
    return False


def suggest_standard_panel(supplier, needed_length_mm, needed_width_mm, door_type=None, range_name=None):
    """
    Smallest standard panel that covers a needed (length, width),
    trimmed down on site to the exact size. If the selected range
    prices panels as doors (see panels_priced_as_door), its own door
    size grid is used as the panel options instead of the supplier's
    generic panel list. Returns the best match per panel type/range,
    or None for one where nothing standard covers the requirement
    (needs Made to Measure instead).
    """
    if door_type and range_name and panels_priced_as_door(supplier, door_type, range_name):
        sizes = standard_sizes(supplier, door_type, range_name)
        candidates = [(l, w) for l, w in sizes if l >= needed_length_mm and w >= needed_width_mm]
        label = f"{range_name} (priced as door)"
        return {label: min(candidates, key=lambda s: s[0] * s[1]) if candidates else None}

    results = {}
    for panel_type, sizes in PANEL_STANDARD_SIZES.get(supplier, {}).items():
        candidates = [(l, w) for l, w in sizes if l >= needed_length_mm and w >= needed_width_mm]
        if candidates:
            # smallest total area that still covers the requirement
            results[panel_type] = min(candidates, key=lambda s: s[0] * s[1])
        else:
            results[panel_type] = None
    return results


